namespace Alpha.CloneAccount.Api.App_Start
{
    using Alpha.CloneAccount.Api.Utilities;
    using Controllers;
    using Fanex.Data.Repository;
    using Fanex.Logging;
    using MediatR;
    using Services;
    using SimpleInjector;
    using SimpleInjector.Integration.WebApi;
    using SimpleInjector.Lifestyles;
    using Sunplus.Agent.Utilities;
    using System.Collections.Generic;
    using System.Reflection;
    using System.Web.Http;

    public static class DependencyConfig
    {
        public static void Init()
        {
            var container = new Container();
            container.Options.DefaultScopedLifestyle = new AsyncScopedLifestyle();

            RegisterMediator(container);

            RegisterDataAccesses(container);
            RegisterServices(container);
            container.RegisterWebApiControllers(GlobalConfiguration.Configuration);

            container.Verify();

            GlobalConfiguration.Configuration.DependencyResolver = new SimpleInjectorWebApiDependencyResolver(container);
        }

        private static void RegisterMediator(Container container)
        {
            var assemblies = GetAssemblies();
            container.RegisterSingleton<IMediator, Mediator>();
            container.Register(typeof(IRequestHandler<,>), assemblies);

            //var notificationHandlerTypes = container.GetTypesToRegister(
            //    typeof(INotificationHandler<>),
            //    assemblies,
            //    new TypesToRegisterOptions
            //    {
            //        IncludeGenericTypeDefinitions = true,
            //        IncludeComposites = false,
            //    });
            //container.Collection.Register(typeof(INotificationHandler<>), notificationHandlerTypes);

            // Pipeline
            container.Collection.Register(typeof(IPipelineBehavior<,>), new[]
            {
                typeof(GenericPipelineBehavior<,>)
            });

            container.Register(() => new ServiceFactory(container.GetInstance), Lifestyle.Singleton);
        }

        private static IEnumerable<Assembly> GetAssemblies()
        {
            yield return typeof(BaseApiController).GetTypeInfo().Assembly;
        }

        private static void RegisterDataAccesses(Container container)
        {
            container.RegisterSingleton<IDynamicRepository, DynamicRepository>();
        }

        private static void RegisterServices(Container container)
        {
            container.RegisterSingleton(() => Fanex.Logging.Logger.Log);

            container.RegisterSingleton<Encryptor, EncryptorImpl>();
            container.Register<ICustomerService, CustomerServiceImpl>(Lifestyle.Scoped);
            container.Register<IBalanceService, BalanceService>(Lifestyle.Scoped);
            container.RegisterSingleton<PasswordService, PasswordServiceImpl>();
            container.RegisterSingleton<SportbooksCopyMemberSpParamsBuilder, SportbooksCopyMemberSpParamsBuilderImpl>();
            container.Register<ThirdPartyProductService, ThirdPartyProductServiceImpl>(Lifestyle.Scoped);
            container.RegisterSingleton<DCSService, DCSServiceImpl>();
            container.RegisterSingleton<IShardInfoAccessor, ShardInfoAccessor>();
        }
    }
}